"""python3 para_artifact.py <painel_final.html> <saida_artifact.html>  -> mesma página sem <!doctype>/<html>/<head>/<body> (formato do Artifact)
Acrescenta o script do botão ⟳ Atualizar: quem abre o link com a conta da Daniela (conector Claude Code Remote liberado)
dispara a tarefa agendada de atualização (coleta pela API do Farmbox + republica o link); os demais só recarregam a página."""
import re, sys

import hashlib

def aliviar(h):
    """Guarda a ficha completa de cada AP uma única vez (<template id="detstore">) e deixa os cartões
    (details.card) e os itens "ver dados" (details.apx) com o <div class="det"> vazio; o conteúdo é copiado
    quando o usuário abre o item (evento toggle). Corta ~60% do arquivo (limite do Artifact: 16 MB).
    Recebe o HTML (documento inteiro ou só o corpo) e devolve o HTML aliviado; se a estrutura for inesperada, devolve igual."""
    MARK, OPEN = '</summary><div class="det">', '<div class="det">'
    out, store, pos = [], {}, 0
    while True:
        i = h.find(MARK, pos)
        if i < 0:
            break
        start = i + len(MARK) - len(OPEN)
        d = h.rfind('<details', 0, i)
        tag = h[d:d + 40]
        if not (tag.startswith('<details class="apx"') or tag.startswith('<details class="card"')):
            out.append(h[pos:start + len(OPEN)]); pos = start + len(OPEN)
            continue
        depth, j = 0, start                       # acha o </div> que fecha este <div class="det"> (divs aninhados)
        while True:
            o, c = h.find('<div', j), h.find('</div>', j)
            if c < 0:
                return h
            if 0 <= o < c:
                depth += 1; j = o + 4
            else:
                depth -= 1; j = c + 6
                if depth == 0:
                    break
        inner = h[start + len(OPEN):j - 6]
        k = hashlib.md5(inner.encode('utf-8')).hexdigest()[:10]
        store.setdefault(k, inner)
        out.append(h[pos:start]); out.append('<div class="det" data-d="%s"></div>' % k)
        pos = j
    if not store:
        return h
    out.append(h[pos:])
    res = ''.join(out)
    blob = '<template id="detstore">' + ''.join('<div data-d="%s">%s</div>' % (k, v) for k, v in store.items()) + '</template>'
    js = ("<script>(function(){"
          "function fill(d){var T=document.getElementById('detstore');if(!T)return;"
          "var x=d.querySelector(':scope>.det[data-d]');if(!x||x.firstChild)return;"
          "var s=T.content.querySelector('[data-d=\"'+x.getAttribute('data-d')+'\"]');if(s)x.innerHTML=s.innerHTML;}"
          "document.addEventListener('toggle',function(e){var d=e.target;"
          "if(d.open&&d.matches&&d.matches('details.apx,details.card'))fill(d);},true);"
          "document.addEventListener('DOMContentLoaded',function(){[].forEach.call(document.querySelectorAll("
          "'details.apx[open],details.card[open]'),fill);});})();</script>")
    # o script vai no INÍCIO do corpo: o 'toggle' dele precisa rodar antes dos outros scripts do painel
    # (um deles monta as abas "Dados da AP / Produtos / Talhões" quando a AP abre e precisa achar a ficha já preenchida)
    m = re.search(r'<body[^>]*>', res)
    res = (res[:m.end()] + js + res[m.end():]) if m else (js + res)
    k = res.rfind('</body>')
    return res + blob if k < 0 else res[:k] + blob + res[k:]

EXTRA_B64 = ""
RODAPE_B64 = ""
JS = r"""
<style>.btatu.rodando{background:#e9dcb8;pointer-events:none}.hatu.rodando{opacity:.6;pointer-events:none}.atumsg{display:block;width:100%;font-size:12.5px;margin-top:6px;color:#F3E6C4}.atumsg b{color:#fff}.hact{flex-wrap:wrap}.hact .atumsg{color:var(--verde);font-size:12px}.hact .atumsg b{color:var(--verde)}</style>
<script>
(() => {
  const TRIG = 'trig_014wkk4enNbAkBNoZaw5j4s4', SRV = 'Claude Code Remote';
  const bt = document.querySelector('.btatu'); if (!bt) return;
  let mcp = null, rodou = false;
  const bts = () => [...document.querySelectorAll('.btatu,.hatu')];
  const rot = t => bts().forEach(b => b.textContent = t);
  const msg = t => { const v = bts().find(e => e.offsetParent) || bt; let m = document.querySelector('.atumsg'); if (!m) { m = document.createElement('span'); m.className = 'atumsg'; v.parentNode.appendChild(m); } m.innerHTML = t; };
  const hh = d => d.toLocaleTimeString('pt-BR', {hour: '2-digit', minute: '2-digit'});
  (async () => { try { mcp = await window.claude?.use?.('mcp'); } catch (e) { mcp = null; }
    if (mcp) { setTimeout(() => rot('⟳ Atualizar do Farmbox'), 2500); rot('⟳ Atualizar do Farmbox'); bt.title = 'Busca os dados novos no Farmbox e atualiza o link (leva uns 5 minutos)'; } })();
  bt.addEventListener('click', async ev => {
    if (!mcp || rodou) return;            // sem conector: o link só recarrega a página (comportamento normal)
    ev.preventDefault();
    bts().forEach(b => b.classList.add('rodando')); rot('⟳ Atualizando…');
    try {
      await mcp.callTool(SRV, 'fire_trigger', {trigger_id: TRIG, text: 'Disparado pelo botão Atualizar do painel em ' + new Date().toLocaleString('pt-BR')});
      rodou = true; const fim = new Date(Date.now() + 5 * 60000);
      msg(`Atualização iniciada às <b>${hh(new Date())}</b>: buscando os dados no Farmbox. Por volta das <b>${hh(fim)}</b> toque em <b>⟳ Recarregar</b> para ver o painel novo.`);
      bts().forEach(b => b.classList.remove('rodando')); rot('⟳ Recarregar');
    } catch (e) {
      bts().forEach(b => b.classList.remove('rodando')); rot('⟳ Atualizar do Farmbox');
      const c = e && e.code;
      msg(c === 'approval_required' || c === 'not_granted' ? 'Para atualizar pelo botão, permita o acesso ao "Claude Code Remote" quando o Claude pedir (menu Permissões do painel).'
        : c === 'needs_reauth' || c === 'server_not_connected' ? 'O conector "Claude Code Remote" não está conectado nesta conta. A página foi só recarregada.'
        : c === 'tool_error' ? 'Não foi possível iniciar a atualização (só a conta da Daniela pode disparar). O painel se atualiza sozinho de hora em hora, das 6h às 19h.'
        : 'Não foi possível iniciar a atualização agora. Tente de novo em instantes.');
    }
  });
})();
</script>
<script>
document.addEventListener('click', e => { const l = e.target.closest && e.target.closest('.vmenu label.chip'); if (!l) return; const d = l.closest('.vmenu');
  const sm = d.querySelector('summary small'); if (sm) sm.textContent = l.textContent.replace(/\s*\d+\s*$/, '').trim() === 'Todos' ? 'toque para filtrar' : '· ' + l.textContent.replace(/\s*\d+\s*$/, '').trim();
  d.parentNode.querySelectorAll('.vmenu').forEach(m => { if (m !== d) { var q = m.querySelector('summary small'); if (q) q.textContent = 'toque para filtrar'; m.open = false; } });
  setTimeout(() => { d.open = false; }, 0); });
</script>
<script>
document.addEventListener('click', function(e){
  var f = e.target.closest && e.target.closest('#apsheet [data-x]'); if (f) { var o = document.getElementById('apsheet'); if (o) o.remove(); return; }
  var l = e.target.closest && e.target.closest('.aplink'); if (!l) return;
  var src = document.querySelector('#apdata [data-ap="' + l.getAttribute('data-ap') + '"]'); if (!src) return;
  var old = document.getElementById('apsheet'); if (old) old.remove();
  var o = document.createElement('div'); o.id = 'apsheet'; o.setAttribute('data-x', '1');
  o.style.cssText = 'position:fixed;inset:0;z-index:99999;background:rgba(0,0,0,.45);display:flex;align-items:flex-end;justify-content:center';
  o.innerHTML = '<div style="background:#fff;width:100%;max-width:640px;max-height:88vh;overflow:auto;border-radius:18px 18px 0 0;padding:14px 16px 24px;box-shadow:0 -6px 24px rgba(0,0,0,.25)"><div style="text-align:right"><button data-x="1" style="border:0;background:#3D6421;color:#fff;border-radius:16px;padding:6px 14px;font:600 13px system-ui">Fechar ✕</button></div>' + src.innerHTML + '</div>';
  o.addEventListener('click', function(ev){ if (ev.target === o) o.remove(); });
  document.body.appendChild(o);
});
</script>
<script>
document.addEventListener('toggle', function(e){ var d = e.target; if (!d.matches || !d.matches('#talhoes details.tal, #variedades details.tal, #variedades details.tlv')) return;
  var cls = d.classList.contains('tlv') ? 'tlv' : 'tal'; var sib = Array.prototype.filter.call(d.parentNode.children, function(x){ return x !== d && x.tagName === 'DETAILS' && x.classList.contains(cls); });
  sib.forEach(function(x){ x.style.display = d.open ? 'none' : ''; });
  if (d.open) { var r = d.getBoundingClientRect(); if (r.top < 0 || r.top > 300) d.scrollIntoView({block: 'start'}); } }, true);
</script>"""
def main():
    h = open(sys.argv[1], encoding='utf-8').read()
    head = re.search(r'<head[^>]*>(.*?)</head>', h, re.S).group(1)
    body = re.search(r'<body[^>]*>(.*)</body>', h, re.S).group(1)
    head = re.sub(r'<meta[^>]*(charset|viewport)[^>]*>', '', head)
    import os, base64, zlib
    EXTRA = zlib.decompress(base64.b64decode(EXTRA_B64)).decode('utf-8')   # tela inicial nova, menu, acordeões etc. (06/11/2026)
    RODAPE = zlib.decompress(base64.b64decode(RODAPE_B64)).decode('utf-8')
    i = body.rfind('</main>')
    if i >= 0:
        j = body.find('<footer', i); k = body.find('</footer>', j)
        body = body[:i] + EXTRA + '\n</main>' + (body[i+7:j] + RODAPE + body[k+9:] if j >= 0 and k >= 0 else body[i+7:] + RODAPE)
    body = aliviar(body)
    open(sys.argv[2], 'w', encoding='utf-8').write(head + '\n' + body + JS)
    print('ok', len(head) + len(body))

if __name__ == '__main__':
    main()
